export type RegistroPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function registroProgram(
  config: { programAddress?: Address | HasAddress } = {}
) {
  return <T extends RegistroPluginRequirements>(
    client: T
  ): ExtendedClient<T, { registro: RegistroPlugin }> => {
    return extendClient(client, {
      registro: <RegistroPlugin>{
        accounts: {
          programaFidelidad: addSelfFetchFunctions(
            client,
            getProgramaFidelidadCodec()
          ),
          metadataFidelidad: addSelfFetchFunctions(
            client,
            getMetadataFidelidadCodec()
          ),
          walletCliente: addSelfFetchFunctions(client, getWalletClienteCodec()),
          indiceWalletConcesionario: addSelfFetchFunctions(
            client,
            getIndiceWalletConcesionarioCodec()
          ),
          puntosVenta: addSelfFetchFunctions(client, getPuntosVentaCodec()),
          catalogoServicios: addSelfFetchFunctions(
            client,
            getCatalogoServiciosCodec()
          ),
          canjeServicio: addSelfFetchFunctions(client, getCanjeServicioCodec()),
          registroGlobal: addSelfFetchFunctions(
            client,
            getRegistroGlobalCodec()
          ),
          concesionario: addSelfFetchFunctions(client, getConcesionarioCodec()),
          moto: addSelfFetchFunctions(client, getMotoCodec()),
          kilometrajeMoto: addSelfFetchFunctions(
            client,
            getKilometrajeMotoCodec()
          ),
          garantia: addSelfFetchFunctions(client, getGarantiaCodec()),
          cliente: addSelfFetchFunctions(client, getClienteCodec()),
          asociacionCliente: addSelfFetchFunctions(
            client,
            getAsociacionClienteCodec()
          ),
          venta: addSelfFetchFunctions(client, getVentaCodec()),
          servicio: addSelfFetchFunctions(client, getServicioCodec()),
          reclamacion: addSelfFetchFunctions(client, getReclamacionCodec()),
        },
        instructions: {
          registrarConcesionario: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getRegistrarConcesionarioInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          configurarGarantia: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getConfigurarGarantiaInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          registrarMoto: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getRegistrarMotoInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          registrarCliente: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getRegistrarClienteInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          registrarAsociacionCliente: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getRegistrarAsociacionClienteInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          registrarVenta: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getRegistrarVentaInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          registrarServicio: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getRegistrarServicioInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          reclamarGarantia: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getReclamarGarantiaInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          eliminarMoto: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getEliminarMotoInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          configurarProgramaFidelidad: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getConfigurarProgramaFidelidadInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          registrarMetadataFidelidad: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getRegistrarMetadataFidelidadInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          actualizarMetadataFidelidad: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getActualizarMetadataFidelidadInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          actualizarPuntosFidelidad: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getActualizarPuntosFidelidadInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          vincularWalletCliente: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getVincularWalletClienteInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          desvincularWalletCliente: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getDesvincularWalletClienteInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          otorgarPuntos: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getOtorgarPuntosInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          inicializarCatalogoServicios: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getInicializarCatalogoServiciosInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          actualizarServicioCatalogo: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getActualizarServicioCatalogoInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          agregarServicioCatalogo: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getAgregarServicioCatalogoInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
          canjearServicio: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCanjearServicioInstruction(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              })
            ),
        },
        identifyAccount: identifyRegistroAccount,
        identifyInstruction: identifyRegistroInstruction,
        parseInstruction: parseRegistroInstruction,
      },
    });
  };
}
